package cn.adc.duration;
import cn.adc.shared.audit.*;import cn.adc.shared.security.*;import cn.adc.shared.config.*;import jakarta.servlet.http.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import tools.jackson.databind.JsonNode;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class DurationControllerTest {
 @Test void paginationBoundaryDoesNotDefaultInvalidLimits()throws Exception {mvc.perform(get("/api/v1/staff/duration-projects?limit=0")).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/staff/duration-projects?limit=101")).andExpect(status().isBadRequest());}
 static class Stub implements DurationOperations {
  int writes;List<JsonNode> rows=List.of();CommandRecovery.Receipt saved;String expectedReference;
  public CommandRecovery.Receipt create(UUID k,JsonNode n){writes++;return saved;}public CommandRecovery.Receipt edit(UUID k,long i,int v,JsonNode n){writes++;return saved;}public CommandRecovery.Receipt publish(UUID k,long i,int v,JsonNode n){writes++;return saved;}public CommandRecovery.Receipt recover(String r){assertEquals(expectedReference,r);return saved;}public JsonNode version(long i,int v){return rows.getFirst();}public List<JsonNode> current(){return rows;}public Map<String,Boolean> capabilities(){return Map.of("canEdit",true,"canPublish",false);}public String requestNamespace(){return "HQCFG/v1/"+"a".repeat(32);}
 }
 Stub service;MockMvc mvc;String csrf="SYNTHETIC-csrf";boolean signedIn=true;
 @BeforeEach void setup(){service=new Stub();var session=new StaffSessionIdentityAdapter(()->signedIn?new StaffSessionIdentityAdapter.VerifiedSession("SYNTHETIC-hq",csrf,new SourceStamp("SYNTHETIC","v1","reviewer",Instant.EPOCH,true)):null);mvc=MockMvcBuilders.standaloneSetup(new DurationController(new DurationAccess(){public DurationOperations service(HttpServletRequest r){return service;}public StaffSessionIdentityAdapter identity(HttpServletRequest r){return session;}})).build();}
 @Test void unauthenticatedAndCsrfSpoofNeverInvokeWrites()throws Exception {signedIn=false;mvc.perform(post("/api/v1/headquarters/duration-project-drafts").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{}")).andExpect(status().isUnauthorized());signedIn=true;mvc.perform(post("/api/v1/headquarters/duration-project-drafts").header("Idempotency-Key",UUID.randomUUID()).header("X-CSRF-Token","wrong").contentType("application/json").content("{}")).andExpect(status().isForbidden());assertEquals(0,service.writes);}
 @Test void unknownAndAuditPersistenceAreSeparateAndRawReferenceQueryRoutes()throws Exception {String ref="HQCFG/v1/"+"a".repeat(32)+"/DURATION_PUBLISH/"+UUID.randomUUID();service.expectedReference=ref;service.saved=new CommandRecovery.Receipt(ref,"UNKNOWN",CommandRecovery.Persistence.NOT_PERSISTED,null,true);mvc.perform(get("/api/v1/headquarters/duration-commands/"+ref)).andExpect(status().isAccepted()).andExpect(jsonPath("$.status").value("UNKNOWN")).andExpect(jsonPath("$.auditPersistence").value("NOT_PERSISTED"));}
 @Test void strictFloatRejectionStillCallsAuditedService()throws Exception {service.saved=new CommandRecovery.Receipt("SYNTHETIC-ref","REJECTED",CommandRecovery.Persistence.CONFIRMED,null,false);mvc.perform(post("/api/v1/headquarters/duration-project-drafts").header("Idempotency-Key",UUID.randomUUID()).header("X-CSRF-Token",csrf).contentType("application/json").content("{\"projectName\":\"SYNTHETIC\",\"durationMinutes\":1.0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.status").value("REJECTED"));assertEquals(1,service.writes);}
 @Test void currentVersionDtoCarriesServerTokenWithoutChangingDatabaseColumns()throws Exception {var row=AuditDocuments.parse("{\"project_id\":1,\"duration_version_no\":1,\"project_name\":\"SYNTHETIC\",\"duration_minutes\":30,\"publication_status\":\"CURRENT\",\"published_at\":\"2026-11-05T00:00Z\",\"published_by\":\"SYNTHETIC\",\"publication_evidence\":{}}");service.rows=List.of(row);mvc.perform(get("/api/v1/staff/duration-projects")).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].projectId").value("1")).andExpect(jsonPath("$.items[0].stateToken").value(AuditDocuments.hash(row)));}
}
